import{_ as l,c as i,o as e,ao as o}from"./chunks/framework.C3XuLvUm.js";const q=JSON.parse('{"title":"Pogget 灵感小站服务协议","description":"","frontmatter":{"next":false},"headers":[],"relativePath":"agreement/pogget-vui-service.md","filePath":"agreement/pogget-vui-service.md"}'),t={name:"agreement/pogget-vui-service.md"};function r(n,a,h,u,s,d){return e(),i("div",null,a[0]||(a[0]=[o('<h1 id="pogget-灵感小站服务协议" tabindex="-1">Pogget 灵感小站服务协议 <a class="header-anchor" href="#pogget-灵感小站服务协议" aria-label="Permalink to &quot;Pogget 灵感小站服务协议&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">版本</p><p>初版发布日期：2025 年 11 月 9 日</p><p>最近更新日期：2025 年 11 月 9 日</p></div><h2 id="一、总则" tabindex="-1">一、总则 <a class="header-anchor" href="#一、总则" aria-label="Permalink to &quot;一、总则&quot;">​</a></h2><h3 id="_1-1-协议主体与范围" tabindex="-1">1.1 协议主体与范围 <a class="header-anchor" href="#_1-1-协议主体与范围" aria-label="Permalink to &quot;1.1 协议主体与范围&quot;">​</a></h3><p>本《Pogget 灵感小站服务协议》（以下简称&quot;本协议&quot;）由 Vilinko Studio（以下简称&quot;本公司&quot;或&quot;平台运营方&quot;）与使用 Pogget 灵感小站服务的用户（以下简称&quot;用户&quot;或&quot;您&quot;）共同缔结。本协议旨在规范用户使用本服务过程中的各项权利、义务和责任。</p><h3 id="_1-2-协议效力与修改" tabindex="-1">1.2 协议效力与修改 <a class="header-anchor" href="#_1-2-协议效力与修改" aria-label="Permalink to &quot;1.2 协议效力与修改&quot;">​</a></h3><ol><li>本协议包括协议正文及所有平台已经发布或将来可能发布的各类规则、公告、通知等内容。所有规则为本协议不可分割的组成部分，与本协议正文具有同等法律效力。</li><li>本公司保留在必要时修改本协议条款的权利。修改后的协议将在平台显著位置公示，自公示之日起满七日即视为已通知用户。若用户不同意相关修改，应立即停止使用本服务；继续使用本服务将视为接受修改后的协议。</li><li>本条款是《Vilinko Studio 软件服务协议》的补充条款，与上述协议具有同等法律效力。若本条款与其他协议内容不一致，优先适用本条款。</li></ol><h2 id="二、定义与解释" tabindex="-1">二、定义与解释 <a class="header-anchor" href="#二、定义与解释" aria-label="Permalink to &quot;二、定义与解释&quot;">​</a></h2><h3 id="_2-1-术语定义" tabindex="-1">2.1 术语定义 <a class="header-anchor" href="#_2-1-术语定义" aria-label="Permalink to &quot;2.1 术语定义&quot;">​</a></h3><ol><li><strong>&quot;Pogget灵感小站&quot;</strong>：指内置于Pogget电脑执行程序中的数字化内容共享平台，为用户提供自定义组件的上传、展示、传播及下载等服务的综合性网络平台。</li><li><strong>&quot;自定义组件&quot;</strong>：指用户通过平台认可的技术规范开发的，能够在Pogget程序运行环境中实现特定功能的数字化作品，包括但不限于功能模块、界面主题、特效素材等。</li><li><strong>&quot;飞书文档系统&quot;</strong>：指本公司采用的用户信息采集与处理平台，用于实现用户提交内容的规范化收集、脱敏处理及分类存储。</li><li><strong>&quot;用户身份标识符&quot;</strong>：指在组件通过审核后，由平台技术系统自动嵌入的、经过加密混淆处理的数字身份识别代码，用于组件溯源及版权保护。</li></ol><h2 id="三、服务内容与规范" tabindex="-1">三、服务内容与规范 <a class="header-anchor" href="#三、服务内容与规范" aria-label="Permalink to &quot;三、服务内容与规范&quot;">​</a></h2><h3 id="_3-1-服务范围说明" tabindex="-1">3.1 服务范围说明 <a class="header-anchor" href="#_3-1-服务范围说明" aria-label="Permalink to &quot;3.1 服务范围说明&quot;">​</a></h3><p>Pogget灵感小站为用户提供以下专业技术服务：</p><ol><li><strong>组件收集服务</strong>：按照<u>平台制定的技术规范</u>接收用户提交的自定义组件</li><li><strong>内容审核服务</strong>：对用户提交组件进行<u>内容合规性审查</u>及<u>技术安全性检测</u></li><li><strong>组件分发服务</strong>：为<u>通过审核的组件</u>提供平台展示及网络分发服务</li><li><strong>技术支持服务</strong>：为组件开发者提供<u>技术指导</u>及<u>运营维护支持</u></li></ol><h3 id="_3-2-服务标准与保证" tabindex="-1">3.2 服务标准与保证 <a class="header-anchor" href="#_3-2-服务标准与保证" aria-label="Permalink to &quot;3.2 服务标准与保证&quot;">​</a></h3><ol><li>本公司将按照行业标准采取合理的技术措施保障服务的稳定运行。</li><li>用户理解并同意，因系统维护、升级或不可抗力等因素可能导致服务临时中断，本公司不因此承担任何责任。</li></ol><h2 id="四、用户权利与义务" tabindex="-1">四、用户权利与义务 <a class="header-anchor" href="#四、用户权利与义务" aria-label="Permalink to &quot;四、用户权利与义务&quot;">​</a></h2><h3 id="_4-1-用户基本权利" tabindex="-1">4.1 用户基本权利 <a class="header-anchor" href="#_4-1-用户基本权利" aria-label="Permalink to &quot;4.1 用户基本权利&quot;">​</a></h3><p>在严格遵守本协议的前提下，用户享有以下基本权利：</p><ol><li><strong>组件上传权</strong>：按照平台技术规范提交符合要求的自定义组件</li><li><strong>组件使用权</strong>：下载并使用平台已上架组件的非独占性权利</li><li><strong>内容管理权</strong>：对本人上传组件进行更新、下架等管理操作</li><li><strong>违规举报权</strong>：对平台内存在的违规内容进行实名或匿名举报</li></ol><h3 id="_4-2-用户义务与责任" tabindex="-1">4.2 用户义务与责任 <a class="header-anchor" href="#_4-2-用户义务与责任" aria-label="Permalink to &quot;4.2 用户义务与责任&quot;">​</a></h3><p>用户承诺严格遵守以下义务：</p><ol><li>保证提交的所有资料真实、准确、完整且符合法律法规要求</li><li>确保上传组件不侵犯任何第三方的合法权益</li><li>及时维护和更新本人上传的组件内容</li><li>配合平台进行必要的身份验证和内容审核</li></ol><h2 id="五、平台权利与责任" tabindex="-1">五、平台权利与责任 <a class="header-anchor" href="#五、平台权利与责任" aria-label="Permalink to &quot;五、平台权利与责任&quot;">​</a></h2><h3 id="_5-1-平台管理权限" tabindex="-1">5.1 平台管理权限 <a class="header-anchor" href="#_5-1-平台管理权限" aria-label="Permalink to &quot;5.1 平台管理权限&quot;">​</a></h3><p>为确保平台生态健康发展，本公司保留以下管理权限：</p><ol><li><strong>内容审核权</strong>：对<u>所有用户提交的组件</u>进行实质性审查，确保符合平台技术规范和法律法规要求</li><li><strong>内容处置权</strong>：对<u>违反规定</u>的组件采取<u>删除、修改、下架</u>等措施，维护平台秩序和用户权益</li><li><strong>账号管理权</strong>：对<u>违规用户</u>采取<u>警告、限制功能、封禁账号</u>等处置，保护用户隐私和平台安全</li><li><strong>服务管理权</strong>：通过<u>公告方式</u>调整服务内容或暂停服务运营，确保用户满意度和平台运营效率</li></ol><h3 id="_5-2-平台责任限制" tabindex="-1">5.2 平台责任限制 <a class="header-anchor" href="#_5-2-平台责任限制" aria-label="Permalink to &quot;5.2 平台责任限制&quot;">​</a></h3><ol><li><strong>本公司不对用户生成内容的合法性、准确性作任何明示或默示的保证</strong></li><li>因<u>用户行为</u>导致的任何直接或间接损失，本公司<u>不承担法律责任</u></li><li>本公司<u>不保证</u>服务的<u>连续性、及时性、安全性不受影响</u></li></ol><h2 id="六、知识产权保护" tabindex="-1">六、知识产权保护 <a class="header-anchor" href="#六、知识产权保护" aria-label="Permalink to &quot;六、知识产权保护&quot;">​</a></h2><h3 id="_6-1-权利归属" tabindex="-1">6.1 权利归属 <a class="header-anchor" href="#_6-1-权利归属" aria-label="Permalink to &quot;6.1 权利归属&quot;">​</a></h3><ol><li>平台运营方独立拥有本服务相关的<u>商标权、专利权、著作权</u>等知识产权</li><li>用户保留对其上传组件的<u>原始</u>知识产权</li></ol><h3 id="_6-2-授权许可" tabindex="-1">6.2 授权许可 <a class="header-anchor" href="#_6-2-授权许可" aria-label="Permalink to &quot;6.2 授权许可&quot;">​</a></h3><p><u>用户上传组件即视为授予本公司一项全球范围内、免费的、不可撤销的普通使用许可，允许本公司为提供服务之目的使用、复制、修改、传播其组件内容。</u></p><h3 id="_6-3-标识符技术措施" tabindex="-1">6.3 标识符技术措施 <a class="header-anchor" href="#_6-3-标识符技术措施" aria-label="Permalink to &quot;6.3 标识符技术措施&quot;">​</a></h3><p>为保护知识产权，本公司将在组件审核通过后实施以下技术措施：</p><ol><li>嵌入经过加密处理的用户身份识别代码</li><li>添加用于组件验证的数字签名信息</li><li>采用防篡改技术保护组件完整性 用户知悉并同意上述技术措施的实施。</li></ol><h2 id="七、隐私与数据保护" tabindex="-1">七、隐私与数据保护 <a class="header-anchor" href="#七、隐私与数据保护" aria-label="Permalink to &quot;七、隐私与数据保护&quot;">​</a></h2><h3 id="_7-1-信息收集范围" tabindex="-1">7.1 信息收集范围 <a class="header-anchor" href="#_7-1-信息收集范围" aria-label="Permalink to &quot;7.1 信息收集范围&quot;">​</a></h3><p>本公司通过飞书文档系统收集以下信息：</p><ol><li>用户第一次上传组件时填写的<u>微信、QQ、邮箱信息</u></li><li>用户上传 vui 组件的文件数据</li><li>飞鼠表格填写时可能自动收集的用户浏览器信息、IP地址等</li></ol><h3 id="_7-2-信息使用规范" tabindex="-1">7.2 信息使用规范 <a class="header-anchor" href="#_7-2-信息使用规范" aria-label="Permalink to &quot;7.2 信息使用规范&quot;">​</a></h3><ol><li>严格遵循 &quot;合法、正当、必要&quot; 原则使用用户信息</li><li>对<u>用户个人信息</u>进行脱敏处理和加密存储</li><li>建立严格的数据访问权限管理制度</li><li>定期开展信息安全风险评估和审计</li><li>对于更加详细的隐私政策请查阅《Vilinko Studio 隐私政策》</li></ol><h2 id="八、免责条款" tabindex="-1">八、免责条款 <a class="header-anchor" href="#八、免责条款" aria-label="Permalink to &quot;八、免责条款&quot;">​</a></h2><h3 id="_8-1-免责情形" tabindex="-1">8.1 免责情形 <a class="header-anchor" href="#_8-1-免责情形" aria-label="Permalink to &quot;8.1 免责情形&quot;">​</a></h3><p><strong>在下列情形下，本公司不承担法律责任：</strong></p><ol><li>因<u>不可抗力</u>导致的服务中断或数据丢失</li><li><u>用户操作不当</u>造成的损失或损害</li><li><u>第三方行为</u>导致的纠纷或损失</li><li>用户违反本协议约定产生的后果</li></ol><h2 id="九、附则" tabindex="-1">九、附则 <a class="header-anchor" href="#九、附则" aria-label="Permalink to &quot;九、附则&quot;">​</a></h2><h3 id="_9-1-争议解决" tabindex="-1">9.1 争议解决 <a class="header-anchor" href="#_9-1-争议解决" aria-label="Permalink to &quot;9.1 争议解决&quot;">​</a></h3><p>因本协议引起的任何争议，双方应友好协商解决；协商不成的，任何一方均有权向本公司所在地有管辖权的人民法院提起诉讼。</p><h3 id="_9-2-通知送达" tabindex="-1">9.2 通知送达 <a class="header-anchor" href="#_9-2-通知送达" aria-label="Permalink to &quot;9.2 通知送达&quot;">​</a></h3><p>本公司将通过以下方式向用户发送法律文书：</p><ol><li>平台公告</li><li>用户注册邮箱</li><li>站内信息系统 上述方式发送的法律文书自发出之日起即视为送达。</li></ol><h2 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to &quot;附录&quot;">​</a></h2><ol><li>如果您对本协议有问题，请您发送邮件到 <a href="mailto:privacy@vilinko.com" target="_blank" rel="noreferrer">privacy@vilinko.com</a> ，我们将在 7 个工作日内回复您。</li><li>飞书用户协议：<a href="https://www.feishu.cn/terms" target="_blank" rel="noreferrer">https://www.feishu.cn/terms</a></li><li>飞书隐私政策：<a href="https://www.feishu.cn/privacy" target="_blank" rel="noreferrer">https://www.feishu.cn/privacy</a></li><li>飞书安全与合规：<a href="https://www.feishu.cn/security" target="_blank" rel="noreferrer">https://www.feishu.cn/security</a></li></ol>',55)]))}const g=l(t,[["render",r]]);export{q as __pageData,g as default};
